ape(width, height, radius) {
  const shape = new THREE.Shape();
  const x = -width / 2;
  const y = -height / 2;
  const r = Math.min(radius, width / 2, height / 2);
  shape.moveTo(x, y + r);
  shape.lineTo(x, y + height - r);
  shape.quadraticCurveTo(x, y + height, x + r, y + height);
  shape.lineTo(x + width - r, y + height);
  shape.quadraticCurveTo(x + width, y + height, x + width, y + height - r);
  shape.lineTo(x + width, y + r);
  shape.quadraticCurveTo(x + width, y, x + width - r, y);
  shape.lineTo(x + r, y);
  shape.quadraticCurveTo(x, y, x, y + r);
  return shape;
}

function disposeObject3D(object) {
  if (!object) return;
  object.traverse((child) => {
    if (child.geometry) {
      child.geometry.dispose();
    }
    if (child.material) {
      const materials = Array.isArray(child.material) ? child.material : [child.material];
      materials.forEach((mat) => {
        if (mat.map && typeof mat.map.dispose === 'function') mat.map.dispose();
        if (typeof mat.dispose === 'function') mat.dispose();
      });
    }
  });
}

export default function createNode(config, ctx) {
  const colors = { ...DEFAULT_COLORS, ...(config.colors || {}) };
  const typography = { ...DEFAULT_TYPOGRAPHY, ...(config.typography || {}) };
  const textContent =
    Array.isArray(config.textContent) && config.textContent.length
      ? config.textContent
      : DEFAULT_TEXT_CONTENT;
  const primitiveRefs = Array.isArray(config.cinematicPrimitives)
    ? config.cinematicPrimitives
    : [];

  const sp = config.scenePosition || {};
  const pos = { x: sp.x ?? 0, y: sp.y ?? 0, z: sp.z ?? 0 };
  const rot = sp.rotationXYZ || { x: 0, y: 0, z: 0 };
  const scl = sp.scaleXYZ || { x: 1, y: 1, z: 1 };

  // --- geometry: rounded-rect button, extruded with a 45-degree machined chamfer
  const shape = createRoundedRectShape(WIDTH, HEIGHT, RADIUS);
  const geometry = new THREE.ExtrudeGeometry(shape, {
    depth: CORE_DEPTH,
    bevelEnabled: true,
    bevelThickness: BEVEL,
    bevelSize: BEVEL,
    bevelSegments: 2,
    curveSegments: 12,
  });
  geometry.center();
  geometry.computeVertexNormals();

  // --- TSL surface: engineered vertical gradient with a hard machined seam,
  // plus a normal-driven accent edge light on the chamfer/perimeter faces.
  const stops =
    colors.gradientStops && colors.gradientStops.length === 3
      ? colors.gradientStops
      : DEFAULT_COLORS.gradientStops;
  const seamAt = stops[1].at ?? 0.55;

  const topColor = color(stops[0].hex);
  const midColor = color(stops[1].hex);
  const bottomColor = color(stops[2].hex);
  const edgeAccentColor = color(colors.accent);

  const posFactor = oneMinus(uv().y); // 0 at top of face, 1 at bottom
  const stageA = clamp(posFactor.div(float(seamAt)), float(0.0), float(1.0));
  const stageB = clamp(
    posFactor.sub(float(seamAt)).div(float(1.0 - seamAt)),
    float(0.0),
    float(1.0),
  );
  const colorA = mix(topColor, midColor, stageA);
  const colorB = mix(midColor, bottomColor, stageB);
  const seamSwitch = step(float(seamAt), posFactor);
  const baseGradient = mix(colorA, colorB, seamSwitch);

  // hard 0.01-unit seam line at 50% face height (no soft blur, engraved groove)
  const seamHalfWidth = float(0.0075);
  const seamDistance = abs(posFactor.sub(float(0.5)));
  const seamMask = step(seamDistance, seamHalfWidth);
  const groovedGradient = mix(baseGradient, baseGradient.mul(float(0.55)), seamMask);

  // normal-driven face/edge split: caps get the gradient, chamfer/perimeter gets the accent glow
  const normalFacing = abs(normalLocal.z);
  const faceMask = step(float(0.9), normalFacing);

  const edgeIntensity = uniform(1.6);
  const emissiveEdge = edgeAccentColor.mul(edgeIntensity);

  const colorNode = mix(edgeAccentColor, groovedGradient, faceMask);
  const emissiveNode = mix(emissiveEdge, vec3(0, 0, 0), faceMask);

  const material = new THREE.MeshPhysicalNodeMaterial({
    roughness: 0.5,
    metalness: 0.35,
    clearcoat: 0.22,
    clearcoatRoughness: 0.2,
    side: THREE.FrontSide,
  });
  material.colorNode = colorNode;
  material.emissiveNode = emissiveNode;
  if ('anisotropy' in material) {
    material.anisotropy = 0.4;
    material.anisotropyRotation = Math.PI / 2;
  }

  const buttonMesh = new THREE.Mesh(geometry, material);
  buttonMesh.name = 'gradient-cta-button';

  // --- contact shadow, tightens on press
  const shadowGeometry = new THREE.PlaneGeometry(WIDTH * 1.06, HEIGHT * 1.35);
  const shadowOpacity = uniform(0.35);
  const shadowMaterial = new THREE.MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
  });
  shadowMaterial.colorNode = color(0x000000);
  shadowMaterial.opacityNode = shadowOpacity;
  const shadowMesh = new THREE.Mesh(shadowGeometry, shadowMaterial);
  shadowMesh.name = 'gradient-cta-contact-shadow';
  shadowMesh.position.set(0, -HEIGHT / 2 - 0.08, -0.01);

  // --- text (MSDF, via ctx.fontAtlas — never TextGeometry/DOM)
  const ctaEntry =
    textContent.find((t) => t.role === 'cta-label') || DEFAULT_TEXT_CONTENT[0];
  const captionEntry =
    textContent.find((t) => t.role === 'caption') || DEFAULT_TEXT_CONTENT[1];
  const ctaStyle = typography['cta-label'] || DEFAULT_TYPOGRAPHY['cta-label'];
  const captionStyle = typography.caption || DEFAULT_TYPOGRAPHY.caption;

  const ctaLabelMesh = createTextMesh(ctx, {
    text: ctaEntry.text,
    font: ctaStyle.family,
    fontWeight: ctaStyle.fontWeight,
    fontSize: (ctaStyle.fontSize || 20) / 100,
    letterSpacing: ctaStyle.letterSpacing,
    lineHeight: ctaStyle.lineHeight,
    color: colors.paper,
    maxWidth: WIDTH - 0.5,
    anchorX: 'center',
    anchorY: 'middle',
  });
  ctaLabelMesh.name = 'gradient-cta-label';
  ctaLabelMesh.position.set(0, 0, FRONT_Z);

  const captionMesh = createTextMesh(ctx, {
    text: captionEntry.text,
    font: captionStyle.family,
    fontWeight: captionStyle.fontWeight,
    fontSize: (captionStyle.fontSize || 9) / 100,
    letterSpacing: captionStyle.letterSpacing,
    lineHeight: captionStyle.lineHeight,
    color: colors.paper,
    anchorX: 'center',
    anchorY: 'middle',
  });
  captionMesh.name = 'gradient-cta-caption';
  captionMesh.position.set(0, -HEIGHT / 2 - 0.25, 0.02);

  // --- assembly
  const group = new THREE.Group();
  group.name = 'gradient-cta-object';
  group.add(shadowMesh, buttonMesh, ctaLabelMesh, captionMesh);
  group.position.set(pos.x, pos.y, pos.z);
  group.rotation.set(rot.x || 0, rot.y || 0, rot.z || 0);

  const targetScale = { x: scl.x ?? 1, y: scl.y ?? 1, z: scl.z ?? 1 };
  group.scale.set(targetScale.x * 1.04, targetScale.y * 1.04, targetScale.z * 1.04);

  // --- motion: mount = weighted-settle (overshoot 1.04 -> 1.0, power4.out, 0.9s)
  const mountTl = gsap.timeline();
  mountTl.to(group.scale, {
    x: targetScale.x,
    y: targetScale.y,
    z: targetScale.z,
    duration: 0.9,
    ease: 'power4.out',
  });

  // --- motion: hover = edge light intensifies + button lifts toward camera
  const hoverTl = gsap.timeline({ paused: true });
  hoverTl.to(buttonMesh.position, { z: 0.06, duration: 0.18, ease: 'power2.out' }, 0);
  hoverTl.to(edgeIntensity, { value: 2.2, duration: 0.18, ease: 'power2.out' }, 0);

  // --- motion: press-down (scale 0.97, 120ms, back.out); contact shadow tightens
  const pressTl = gsap.timeline({ paused: true });
  pressTl.to(
    buttonMesh.scale,
    { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' },
    0,
  );
  pressTl.to(shadowMesh.scale, { x: 0.88, y: 0.88, duration: 0.12, ease: 'back.out(2)' }, 0);
  pressTl.to(shadowOpacity, { value: 0.5, duration: 0.12, ease: 'back.out(2)' }, 0);

  let isPressed = false;

  primitiveRefs.forEach((primitive) => {
    const applyPrimitive = ctx.primitives && ctx.primitives[primitive.name];
    if (typeof applyPrimitive === 'function') {
      applyPrimitive(group, primitive.params || {});
    }
  });

  group.userData.handlers = {
    onPointerOver: () => {
      hoverTl.play();
    },
    onPointerOut: () => {
      hoverTl.reverse();
      if (isPressed) {
        isPressed = false;
        pressTl.reverse();
      }
    },
    onPointerDown: () => {
      isPressed = true;
      pressTl.play();
    },
    onPointerUp: () => {
      if (isPressed) {
        isPressed = false;
        pressTl.reverse();
      }
    },
  };

  group.userData.cleanup = () => {
    mountTl.kill();
    hoverTl.kill();
    pressTl.kill();
    disposeObject3D(buttonMesh);
    disposeObject3D(shadowMesh);
    disposeObject3D(ctaLabelMesh);
    disposeObject3D(captionMesh);
    group.userData.handlers = {};
    group.clear();
  };

  return group;
}
